 assert rd(H/'SCALAR_AUDIT.json')['n']==768;agg=rd(O/'AGGREGATE_ROWS.json');A={x['arm']:x for x in agg if x['group']=='all_six_equal'};v=lambda k:A[k]['mIoU_percent'];p='softtoken_geometric_fusedABC';controls=['original_source','prepared_frozen','real_frozen_fusedABC','softtoken_fusedABC','softtoken_arithmetic_fusedABC','softtoken_shuffled_geometric_fusedABC','real_TTA_fusedABC'];rows=[r for f in O.glob('*_ALL_ROWS_PRIVATE.json') for r in rd(f)];conc=[]
