 dump(H/'DECISION.json',decision);dump(H/'CONCENTRATION_SUMMARY.json',conc)
 complement=[]
 for name,rr in [('all',rows)]+[(n,[r for r in rows if r['source']+'_to_'+r['target']==n]) for n in rd(R/'crossplatform/round108/MATRIX_SEALED.json')['directions']]:
  y=lambda k:np.array([r['arms'][k]['IoU'] for r in rr]);f=y('real_frozen_fusedABC');ce=y('softtoken_fusedABC');po=y(p);ar=y('softtoken_arithmetic_fusedABC');complement.append({'scope':name,'n':len(rr),'CE_better_than_BBF':int((ce>f+1e-12).sum()),'CE_worse_than_BBF':int((ce<f-1e-12).sum()),'geometric_better_than_BBF':int((po>f+1e-12).sum()),'geometric_worse_than_BBF':int((po<f-1e-12).sum()),'arithmetic_better_than_BBF':int((ar>f+1e-12).sum()),'arithmetic_worse_than_BBF':int((ar<f-1e-12).sum()),'GT_oracle_of_two_heads_mIoU_diagnostic':float(np.maximum(f,ce).mean()*100),'not_a_deployable_head_selector':True})
 dump(H/'COMPLEMENTARITY_DIAGNOSTIC.json',complement)
 lines=['# R108 — 已训练soft-token头的冻结证据前提检查','','这不是新增模型或TTA。三个epoch100原模型都已有独立参数的soft-token CE头；其训练目标与contrastive BBF不同，但共享同一原生decoder表示，不能称独立视觉专家。R4在早期权重/队列中测过BBS且较差，本轮仅检验当前三source/R91/真实注册点观测条件是否存在互补。','','## 固定方案','','直接用原prediction_heads[5].sem_cls_scores_head处理已封存R106的A/B/C/fusedABC query_hidden；真实全256token softmax分母、BN eval运行统计、dropout关闭。正跨度仅来自与当前BBF相同的纯文本mask，未用官方标注positive_map、类别或GT跨度；最后no-object255从不作为正token。区域与原A256完全不变。','','CE的主体token概率质量在候选维归一化，然后分别固定等权几何池、等权算术池；打乱CE候选对应保留分数集合。锁定主方法为几何池fusedABC，不依据评分改成算术池。44条受保护媒体别名保留prepared冻结输出，不重解码或另跑头。','','12条全原生工程测试验证原始sourceCE模块提取、真实R91decoder hook、缓存h与独立CPUConv/BN/softmax的一致性。整批预测封存后，独立CPU审计全部端点、source checkpoint权重与原框，再评分。','','## 全部结果','','| 范围 | 方法 | mIoU % | Acc25 % | Acc50 % |','|---|---|---:|---:|---:|']
