 lines+=['','## 六方向与全部负例','','| Source | Target | 方法 | 对照 | Δ pp | 改善/恶化/不变 |','|---|---|---|---|---:|---:|']
 for x in rd(O/'ALL_PAIRED_ROWS.json'):lines.append(f"| {x['source']} | {x['target']} | {x['method']} | {x['control']} | {x['gain_pp']:+.6f} | {x['better']}/{x['worse']}/{x['same']} |")
